def _vulnerable(version: str) -> bool:
    """True if ``version`` falls in the flagged range (< 1.2.6)."""
    try:
        parts = tuple(int(x) for x in version.split("-")[0].split(".")[:3])
    except (ValueError, AttributeError):
        return False
    while len(parts) < 3:
        parts += (0,)
    return parts < (1, 2, 6)


