    def _handle_audit(self, body: bytes):
        try:
            requested = json.loads(body.decode("utf-8", "replace")) if body else {}
        except (ValueError, UnicodeDecodeError):
            requested = {}
        advisories = {}
        critical = 0
        if AUDIT_MODE == "vuln":
            for name, versions in (requested or {}).items():
