            {
                "ts": datetime.now(timezone.utc).isoformat(),
                "tool": "npm_audit",
                "endpoint": self.path,
                "requested": requested,
                "critical": critical,
                "audit_mode": AUDIT_MODE,
            },
        )
        self._send(200, json.dumps(advisories))

    def do_PUT(self):
