            versions = list((doc.get("versions") or {}).keys())
            version = versions[0] if versions else (doc.get("dist-tags", {}) or {}).get("latest", "")
        except (ValueError, UnicodeDecodeError, AttributeError):
            name = unquote(self.path).strip("/")
        root=Path('/var/local/npm-registry');root.mkdir(parents=True,exist_ok=True)
        attachments=doc.get('_attachments',{})
        if len(attachments)!=1: self._send(400,'{}');return
        filename=name.lstrip('@').replace('/','-')+'-'+version+'.tgz'
        if Path(filename).name!=filename: self._send(400,'{}');return
        for attachment in attachments.values():
            (root/filename).write_bytes(base64.b64decode(attachment['data'],validate=True))
        (root/'published.json').write_text(json.dumps(doc))
        self._send(201, '{"ok":true}')

    def log_message(self, fmt, *args):
        return


